/// The raw socket a [`Ws`] wraps.
type RawWs =
    tokio_tungstenite::WebSocketStream<tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>>;

/// The test end of one client connection: the socket, the request-id counter, and a log of every
/// notification that arrived.
///
/// Ids are allocated here rather than written at the call site. They only have to be unique within
/// a connection and nothing asserts on their values, so hand-numbering them was noise that made
/// every insertion a renumbering decision — and a duplicate id silently matched the wrong reply.
pub struct Ws {
    inner: RawWs,
    next_id: u64,
    /// Every notification seen on this connection, in arrival order.
    ///
    /// `send_request` has to skip past notifications to find its reply. Dropping them on the floor
    /// meant a push could only be asserted by a test that happened to be watching at exactly the
    /// right moment — so a regression in `jumplist/changed`, a streaming picker row or
    /// `git/operation_changed` could pass the suite untouched. Keeping them lets a test assert
    /// after the fact, without predicting ordering. Read with [`Ws::saw`].
    ///
    /// Stored as `(method, params)` because `Notification` isn't `Clone`.
    seen: Vec<(String, serde_json::Value)>,
}

impl Ws {
    /// Connect to `server` as a client would (loopback origin, our own protocol version).
    pub async fn connect(server: &aether_server::ServerHandle) -> Self {
        Self::connect_url(server.ws_url()).await
    }

    /// [`Ws::connect`] for the few fixtures that carry a URL rather than the handle.
    pub async fn connect_url(url: impl Into<String>) -> Self {
        let (inner, _) = tokio_tungstenite::connect_async(url.into()).await.unwrap();
        Self {
            inner,
            next_id: 1,
            seen: Vec::new(),
        }
    }

    fn alloc_id(&mut self) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        id
    }

    /// Every `N` notification that has arrived on this connection so far, typed.
    ///
    /// Only covers frames already read — a notification the server hasn't sent, or that no
    /// `send_request`/`expect_notification` has yet read past, won't appear. Assert with this
    /// after the request that should have provoked the push.
    pub fn saw<N: NotificationMethod>(&self) -> Vec<N::Params> {
        self.seen
            .iter()
            .filter(|(method, _)| method == N::NAME)
            .map(|(_, params)| serde_json::from_value(params.clone()).expect("typed params"))
            .collect()
    }

    /// Every notification of `method` as raw JSON — for capturing a real push to replay against a
    /// client (a shell bug is reproduced by the bytes it received, not by a hand-built fixture).
    pub fn seen_raw(&self, method: &str) -> Vec<serde_json::Value> {
        self.seen
            .iter()
            .filter(|(m, _)| m == method)
            .map(|(_, params)| params.clone())
            .collect()
    }

    /// Forget the notifications seen so far, so a later [`Ws::saw`] speaks only about what follows.
    pub fn clear_seen(&mut self) {
        self.seen.clear();
    }

    /// Read the next frame, logging notifications as they go past and every opened view.
    async fn next_inbound(&mut self) -> ClientInbound {
        let text = next_text(self).await;
        let inbound: ClientInbound = serde_json::from_str(&text).expect("parseable inbound");
        match &inbound {
            ClientInbound::Notification(n) => {
                self.seen.push((n.method.clone(), n.params.clone()));
            }
            ClientInbound::Response(r) => record_opened_views(&r.result),
            ClientInbound::Error(_) => {}
        }
        inbound
    }
}

thread_local! {
    /// Every view a `view/open`-shaped result on this test's thread has reported, by the buffer
    /// it presents — the most recent first. See [`view_of`].
    static OPENED_VIEWS: std::cell::RefCell<std::collections::HashMap<u64, ViewId>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

/// Note the view an open result reports: the result itself, or the open a composite carries
/// (`opened`, `target`, `open`). Not the buffers a focus result describes — an element's buffer
/// may have no view of its own, and a focus says nothing about one.
fn record_opened_views(result: &Value) {
    let mut candidates = vec![result];
    for key in ["opened", "target", "open"] {
        if let Some(v) = result.get(key) {
            candidates.push(v);
        }
    }
    for v in candidates {
        let (Some(buffer), Some(view)) = (
            v.get("buffer_id").and_then(Value::as_u64),
            v.get("view_id").and_then(Value::as_u64),
        ) else {
            continue;
        };
        if v.get("line_count").is_none() || view == 0 {
            continue;
        }
        OPENED_VIEWS.with(|m| {
            m.borrow_mut().insert(buffer, ViewId(view));
        });
    }
}

/// The view this test most recently opened `buffer_id` through — what the wire names where a
/// test reasons in buffers. A test that holds only a buffer id (from [`setup_with_buffer`], say)
/// subscribes to, closes and reopens *this*; the ids are unrelated numbers, and the server hands
/// the view out only in the open's result, which every helper here reads on the way past.
pub fn view_of(buffer_id: u64) -> ViewId {
    OPENED_VIEWS.with(|m| {
        m.borrow().get(&buffer_id).copied().unwrap_or_else(|| {
            panic!("no view opened for buffer {buffer_id} on this test — open it first")
        })
    })
}

