/// A collapsible picker window's `Group` header rows as `(header text, count, expanded)` triples —
/// the file's relative path or the label — which is what a collapsed window is made of by default.
/// Non-header rows are skipped.
pub fn group_rows(items: &[PickerItem]) -> Vec<(String, u32, bool)> {
    items
        .iter()
        .filter_map(|i| match i {
            PickerItem::Group {
                header,
                count,
                expanded,
            } => Some((
                match header {
                    GroupHeader::File { relative_path, .. } => relative_path.clone(),
                    GroupHeader::Label { label } => label.clone(),
                },
                *count,
                *expanded,
            )),
            _ => None,
        })
        .collect()
}

/// Expand one file group in a collapsible picker (`picker/set_group`) and return the header's
/// new absolute row plus the reshaped window. The window comes from a follow-up `Keep` re-view's
/// response, not from the set_group push — `send_request` discards notifications while waiting,
/// so the push may already be gone by the time the response is read. Uses request ids `id`
/// through `id + 2`.
pub async fn expand_file_group(
    ws: &mut Ws,
    kind: PickerKind,
    path: &str,
) -> (u32, PickerUpdateParams) {
    // The header is looked up in the live window rather than constructed, which is what a client
    // does — it echoes back a header it was pushed — and keeps the helper honest if a kind's
    // header shape ever changes.
    let window = send_request::<PickerView>(
        ws,
        &PickerViewParams {
            view_id: None,
            reset: PickerReset::Keep,
            ..view_params(kind)
        },
    )
    .await
    .update
    .expect("a Keep re-view carries its window");
    let header = window
        .items()
        .iter()
        .find_map(|i| match i {
            PickerItem::Group { header, .. } => {
                let label = match header {
                    GroupHeader::File { relative_path, .. } => relative_path.as_str(),
                    GroupHeader::Label { label } => label.as_str(),
                };
                (label == path).then(|| header.clone())
            }
            _ => None,
        })
        .unwrap_or_else(|| panic!("no group header labelled {path:?} in the window"));
    let result: PickerSetGroupResult = send_request::<PickerSetGroup>(
        ws,
        &PickerSetGroupParams {
            kind,
            action: PickerGroupAction::Expand { header },
        },
    )
    .await;
    let view = send_request::<PickerView>(
        ws,
        &PickerViewParams {
            view_id: None,
            reset: PickerReset::Keep,
            ..view_params(kind)
        },
    )
    .await;
    (
        result
            .run
            .expect("selected group is present in the ranking")
            .header_row,
        view.update.expect("a Keep re-view carries its window"),
    )
}

/// Drain `picker/update` notifications until one arrives with `ticking: false` (the search has
/// finished). Returns the final params so the caller can assert on hit count and items.
pub async fn drain_grep_until_done(ws: &mut Ws) -> PickerUpdateParams {
    loop {
        let params: PickerUpdateParams = expect_notification::<PickerUpdate>(ws).await;
        if !params.ticking {
            return params;
        }
    }
}

