/// Subscribe a viewport on an already-open buffer and return the window it renders.
///
/// With the inline diff **off**, which is what a client opens with. Removed lines are phantoms of
/// that view — on a patch as much as on an ordinary file — so a test that wants to see them wants
/// [`diffed_window_of`].
pub async fn window_of(ws: &mut Ws, buffer_id: u64) -> aether_protocol::viewport::Window {
    window_with_diff(ws, buffer_id, false).await
}

/// [`window_of`] with the inline diff on: the view that draws removed lines.
pub async fn diffed_window_of(ws: &mut Ws, buffer_id: u64) -> aether_protocol::viewport::Window {
    window_with_diff(ws, buffer_id, true).await
}

async fn window_with_diff(
    ws: &mut Ws,
    buffer_id: u64,
    diff_view: bool,
) -> aether_protocol::viewport::Window {
    let sub: ViewportSubscribeResult = send_request::<ViewportSubscribe>(
        ws,
        &ViewportSubscribeParams {
            view_id: view_of(buffer_id),
            cols: 80,
            rows: 40,
            overscan_rows: 0,
            scroll: ScrollPosition {
                element: 0,
                line: 0,
                sub_row: 0.0,
            },
            focus: None,
            wrap: WrapMode::None,
            continuation_marker_width: 0,
            tab_width: 4,
            diff_view,
        },
    )
    .await;
    // A subscribe loads a screen of one element; these helpers answer for the whole (small) view.
    whole_view(ws, sub.viewport_id, sub.window).await
}

/// Load every row of the view on `viewport_id`, as a client tall enough to show it all would.
pub async fn whole_view(
    ws: &mut Ws,
    viewport_id: u64,
    window: aether_protocol::viewport::Window,
) -> aether_protocol::viewport::Window {
    let total = total_rows(&window);
    if total == 0 {
        return window;
    }
    window_at(ws, viewport_id, &window, 0, total, 0)
        .await
        .window
}

pub async fn resolve_conflict(
    ws: &mut Ws,
    buffer_id: u64,
    side: ConflictSide,
) -> GitResolveConflictResult {
    send_request::<GitResolveConflict>(ws, &GitResolveConflictParams { buffer_id, side }).await
}

/// The content tree of a chrome row. Panics on a baseline row — the two are separate
/// variants precisely so a test can't confuse them.
pub fn chrome_content(row: &Element) -> &[Element] {
    match row {
        Element::Chrome { children, .. } => children,
        _ => panic!("expected a chrome node"),
    }
}

/// The literal text a chrome row draws, left to right.
pub fn chrome_text(row: &Element) -> String {
    chrome_content(row)
        .iter()
        .map(Element::text_content)
        .collect()
}

/// Every chrome node of a window's tree, in order.
pub fn chrome_nodes(window: &aether_protocol::viewport::Window) -> Vec<&Element> {
    fn walk<'a>(n: &'a Element, out: &mut Vec<&'a Element>) {
        match n {
            Element::Stack { children } => children.iter().for_each(|c| walk(c, out)),
            Element::Chrome { .. } => out.push(n),
            _ => {}
        }
    }
    let mut out = Vec::new();
    walk(&window.root, &mut out);
    out
}

// -------- view geometry, the client's way ----------------------------------------------------------
//
// The server no longer says how tall a view is or where a slice sits on screen: the tree does, and
// the client's shared row maths reads it. Tests that model a client use the same functions, so a
// disagreement between the tree and the client's reading of it fails here rather than on screen.

/// Rows the whole view occupies — chrome, one row each, and every editor's height.
pub fn total_rows(window: &aether_protocol::viewport::Window) -> u32 {
    aether_client::grid::total_rows(&window.root, &Measured::default())
}

/// The lines the first editor carrying any has loaded, as `(first, last exclusive)`.
pub fn loaded_lines(window: &aether_protocol::viewport::Window) -> (u32, u32) {
    window
        .root
        .editors()
        .into_iter()
        .find_map(|n| match n {
            Element::Editor { lines, .. } if !lines.is_empty() => Some((
                lines[0].logical_line,
                lines[lines.len() - 1].logical_line + 1,
            )),
            _ => None,
        })
        .unwrap_or((0, 0))
}

/// The absolute row the first loaded slice starts on — the element's start plus the slice's row
/// within it.
pub fn first_loaded_row(window: &aether_protocol::viewport::Window) -> u32 {
    aether_client::grid::painted_rows(window, &Measured::default())
        .into_iter()
        .find_map(|(at, item)| match item {
            aether_client::grid::PaintedRow::Chrome(_) => None,
            _ => Some(at.get()),
        })
        .unwrap_or(0)
}

/// How many rows the loaded slices paint, chrome included — what a client can put on screen.
pub fn painted_rows(window: &aether_protocol::viewport::Window) -> u32 {
    aether_client::grid::painted_rows(window, &Measured::default()).len() as u32
}

/// Load the slices a client showing rows `top..top+rows` (with `overscan` each side) would ask for,
/// exactly as the real client computes them from the tree it holds.
pub async fn window_at(
    ws: &mut Ws,
    viewport_id: u64,
    current: &aether_protocol::viewport::Window,
    top: u32,
    rows: u32,
    overscan: u32,
) -> ViewportWindowResult {
    let slices = aether_client::grid::slices_for(
        &current.root,
        VisualRow(top),
        rows,
        overscan,
        &Measured::default(),
    );
    let anchor = aether_client::grid::anchor_at(current, VisualRow(top), &Measured::default());
    send_request::<ViewportWindow>(
        ws,
        &ViewportWindowParams {
            viewport_id,
            anchor,
            slices,
        },
    )
    .await
}

/// [`window_at`] for a single-element, unwrapped view, where row `top` of the view is line `top`:
/// one slice of element 0 from that row.
pub async fn window_from_row(
    ws: &mut Ws,
    viewport_id: u64,
    top: u32,
    rows: u32,
) -> ViewportWindowResult {
    send_request::<ViewportWindow>(
        ws,
        &ViewportWindowParams {
            viewport_id,
            anchor: ScrollPosition {
                element: 0,
                line: top,
                sub_row: 0.0,
            },
            slices: vec![SliceRequest {
                element: 0,
                from_row: ElementRow(top),
                rows,
            }],
        },
    )
    .await
}
